method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0
    ensures |result| == |xs| - 1
    ensures result[i] == xs[i + 1] * (i + 1) forall i :: 0 <= i < |result|
{
    var n := |xs|;

    if n == 1 {
        result := [];
    } else {
        result := new int[n - 1];
        var i := 0;
        while i < n - 1
            invariant 0 <= i <= n - 1
            invariant |result| == n - 1
        {
            result[i] := xs[i + 1] * (i + 1);
            i := i + 1;
        }
    }
}
```

